const grpc = require('@grpc/grpc-js');
const mongoose = require('mongoose');

const Customer = mongoose.model('Customer');

function updateBillingAddress(call, callback) {
  const { customer_id, street, city, postal_code, country } = call.request;
  const callerCustomerId = call.metadata.get('x-customer-id')[0];

  if (!customer_id) {
    return callback({ code: grpc.status.INVALID_ARGUMENT, message: 'Missing customer_id' });
  }

  // Ensure authenticated client identity matches the target customer_id
  if (!callerCustomerId || callerCustomerId !== customer_id) {
    return callback({
      code: grpc.status.PERMISSION_DENIED,
      message: 'Cannot update billing address of another customer'
    });
  }

  Customer.findByIdAndUpdate(
    customer_id,
    {
      $set: {
        'billing_address.street': street,
        'billing_address.city': city,
        'billing_address.postal_code': postal_code,
        'billing_address.country': country,
        'updated_at': new Date()
      }
    },
    { new: true },
    (err, updatedCustomer) => {
      if (err || !updatedCustomer) {
        return callback({ code: grpc.status.NOT_FOUND, message: 'Customer update failed' });
      }

      callback(null, {
        success: true,
        customer_id: updatedCustomer._id.toString()
      });
    }
  );
}

module.exports = { updateBillingAddress };
